const items = $input.all();
const results = [];

console.log('\n=== KANDIDATEN DISTANZ-EINSTELLUNGEN ===\n');

for (const item of items) {
  const data = item.json;
  const name = data.property_name || 'Unbekannt';
  const distanzFeld = data.property_gewunschte_distanz;

  console.log(`Kandidat: ${name}`);
  console.log(`  Gewünschte Distanz Feld: ${distanzFeld || 'NICHT GESETZT'}`);

  // Parse Distanz
  let distanz = 'Default (50km)';
  if (distanzFeld) {
    const match = distanzFeld.match(/\d+/);
    if (match) {
      distanz = match[0] + 'km';
    }
  }

  console.log(`  Verwendete Distanz: ${distanz}`);
  console.log('');

  results.push({
    json: {
      name: name,
      distanz_feld_wert: distanzFeld || 'NICHT GESETZT',
      verwendete_distanz: distanz
    }
  });
}

console.log('\n=== ALLE VERFÜGBAREN PROPERTIES ===');
if (items.length > 0) {
  const firstItem = items[0].json;
  const properties = Object.keys(firstItem).filter(key => key.startsWith('property_'));
  console.log('Properties:', properties.join(', '));
}

return results;
